INSERT INTO `map` (`id`, `directory`, `instance_type`, `flags`, `pvp`, `name_enus`, `name_flags`, `area_table_id`, `desc_0_enus`, `desc_0_flags`, `desc_1_enus`, `desc_1_flags`, `loading_screen_id`, `minimap_icon_scale`, `corpse_map_id`, `corpse_x`, `corpse_y`, `time_override`, `expansion`, `raid_offset`, `max_players`) VALUES (2177, '2177', 3, 0, 1, 'Arathi Basin Comp Stomp', 16712190, 3358, 'The Arathi Basin is one of the main staging points of war between the humans and the Forsaken in Azeroth.

Arathi Basin is a 15 vs 15 domination battleground, where each side attempts to control the Stables, Blacksmith, Mine, Lumbermill and Farm for as long as possible.

The Defilers\' elite troopers seek to sever the vital connection between the humans and their dwarven allies to the south.

Meanwhile, the League of Arathor seek to reclaim lost lands for their benefactors in Stormwind.', 16712190, 'The Arathi Basin is one of the main staging points of war between the humans and the Forsaken in Azeroth.

Arathi Basin is a 15 vs 15 domination battleground, where each side attempts to control the Stables, Blacksmith, Mine, Lumbermill and Farm for as long as possible.

The League of Arathor seek to reclaim lost lands for their benefactors in Stormwind.

